actions.script:
// ZE-SALES-014 f/u: org-isolate the CSV/XLSX export (standalone render skips the authz filter)
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def _txnFind = ec.entity.find("zenith.erp.pos.PosTransaction")
    .condition("statusId", "PtCompleted")
    .condition("entryDate", "greater-equals", dayStart)
    .condition("entryDate", "less-equals", dayEnd)
if (_org) _txnFind.condition("organizationPartyId", _org)
def txns = _txnFind.list()

def txnIds = txns.collect { it.transactionId }
paymentWiseList = []
grandTotalAmount = BigDecimal.ZERO
grandTotalTxns = 0

if (txnIds) {
    def payments = ec.entity.find("zenith.erp.pos.PosPayment")
        .condition("transactionId", "in", txnIds).list()

    def methodMap = new LinkedHashMap()
    payments.each { p ->
        def method = p.paymentMethod ?: 'Other'
        if (!methodMap[method]) {
            methodMap[method] = [paymentMethod: method, totalAmount: BigDecimal.ZERO,
                transactionCount: 0 as int, percentage: BigDecimal.ZERO]
        }
        methodMap[method].totalAmount += (p.amount ?: 0) as BigDecimal
        methodMap[method].transactionCount++
    }

    def total = methodMap.values().sum { it.totalAmount } ?: BigDecimal.ONE
    methodMap.values().each { m ->
        m.percentage = total > 0 ? (m.totalAmount * 100 / total).setScale(1, java.math.RoundingMode.HALF_UP) : BigDecimal.ZERO
    }

    paymentWiseList = methodMap.values().sort { -(it.totalAmount as BigDecimal) }
    grandTotalAmount = paymentWiseList.sum { it.totalAmount } ?: BigDecimal.ZERO
    grandTotalTxns = paymentWiseList.sum { it.transactionCount } ?: 0
}
